// Content pack 5 — The Bay and the Barren Lands: the rivers of Hudson Bay and James Bay, the
// east coast and Ungava, and the tundra rivers from the Barren Grounds to Baker Lake
// (authored 2026-10-17).
//
// Scope: the Omushkego (Swampy) Cree rivers of the Ontario lowlands (Severn, Winisk,
// Attawapiskat), the Eeyou Istchee rivers of the Quebec side of James Bay (Harricana, Nottaway,
// Rupert, Eastmain, La Grande, Great Whale), Lake Mistassini and Lake Abitibi on the routes
// inland, the Nunavik rivers to Ungava Bay (Koksoak, George), the Sayisi Dene and Caribou Inuit
// rivers of the Barren Grounds (Seal, Kazan, Dubawnt, Baker Lake). People are drawn from the
// Dictionary of Canadian Biography where it has them (Albanel, Isham, Coats, Mitchell, Isbister,
// Graham, Wales, Erlandson, Finlayson, McLean, Bell, Hanbury, Hornby; Wappisis, Miscomote,
// Abishabis, Inukjuarjuk, Nickawa, Zhauwuno-geezhigo-gaubow) and from Wikipedia and the
// Geological Survey reports where it does not (Low, Pike, Seton, J. W. Tyrrell). Same rules as
// the earlier packs; `relocations` moves York Factory to the Hayes, Fort Severn to the Severn and
// Rupert House to the Rupert, whose rows did not exist before.
import type { PackWaterway, PackLink, PackLocation, PackTimelineEvent, PackHistoricalEvent, PackPronunciation, PackGuide } from "./new-france-to-the-gulf";
import type { PackExplorerWithPortrait, PackFigureWithPortrait } from "./pacific-and-russians";

const wiki = (slug: string) => `https://en.wikipedia.org/wiki/${slug}`;
const dcb = (slug: string) => `https://www.biographi.ca/en/bio/${slug}.html`;
const tce = (slug: string) => `https://www.thecanadianencyclopedia.ca/en/article/${slug}`;
const ia = (id: string) => `https://archive.org/details/${id}`;
const W = (title: string, slug: string, description: string): PackGuide => ({ title, authorSource: "Wikipedia", url: wiki(slug), description, gradeLevel: "7-9" });
const DCB = (title: string, slug: string, description: string): PackGuide => ({ title, authorSource: "Dictionary of Canadian Biography", url: dcb(slug), description, gradeLevel: "10-12" });
const TCE = (title: string, slug: string, description: string): PackGuide => ({ title, authorSource: "The Canadian Encyclopedia", url: tce(slug), description, gradeLevel: "7-9" });
const HBCA = (post: string, description: string): PackGuide => ({ title: `${post} post records`, authorSource: "Hudson's Bay Company Archives", publisher: "Archives of Manitoba, Winnipeg", description, gradeLevel: "10-12" });
const PC = (title: string, description: string): PackGuide => ({ title, authorSource: "Parks Canada", description, gradeLevel: "4-6" });
const IA = (title: string, author: string, year: string, id: string, description: string): PackGuide => ({ title, authorSource: author, publisher: "Internet Archive (digitized copy)", year, url: ia(id), description, gradeLevel: "10-12" });

export type { PackImage, PackGuide } from "./new-france-to-the-gulf";

